#include "h3/game.hpp"
#include <fstream>
#include <iostream>
#include <stdexcept>
using namespace h3;
int main(int argc,char**argv){try{
 std::filesystem::path out=argc>1?argv[1]:"/private/tmp/heroesiii-video-campaign";bool legacy=argc>2&&std::string(argv[2])=="legacy";std::filesystem::create_directories(out);Game g;std::string error;auto root=std::filesystem::path(H3_TEST_SOURCE_ROOT);if(!g.importScenario(root/"assets/demo/scenarios/dead-and-buried-1.json",error,8,131,4))throw std::runtime_error(error);
 nlohmann::json turns=nlohmann::json::array(),battles=nlohmann::json::array();int moves=0,visits=0;std::ofstream actions(out/"actions.jsonl");auto choose=[&]{while(!g.hero.levelChoices.empty()){int skill=g.hero.levelChoices.front().skills.front();for(int priority:{Archery,Offense,Armorer,Wisdom,AirMagic,EarthMagic,Logistics,Intelligence})if(std::find(g.hero.levelChoices.front().skills.begin(),g.hero.levelChoices.front().skills.end(),priority)!=g.hero.levelChoices.front().skills.end()){skill=priority;break;}g.chooseSkill(skill);}};
 auto resolve=[&]{while(g.battle){int target=g.battle->targetId,started=g.day,fort=g.battle->siege.fort,iterations=0;if(fort&&!std::filesystem::exists(out/"first-siege.json")){if(!g.save(out/"first-siege.json",error))throw std::runtime_error(error);}while(g.battle&&iterations++<6000){if(legacy&&g.current()&&g.current()->team==0){if(g.hero.spellbook&&g.hero.spells[MagicArrow]&&g.hero.mana>=g.spellCost(MagicArrow)&&g.battle->spellRound!=g.battle->round){auto at=std::find_if(g.battle->units.begin(),g.battle->units.end(),[](auto&u){return u.team==1&&u.hp>0;});if(at!=g.battle->units.end())g.cast(MagicArrow,{at->x,at->y});}if(g.battle)g.legacyBattleAi();}else g.ai();g.takeEvents();}if(g.battle){std::ofstream(out/"stalled-battle.json")<<g.toJson().dump();throw std::runtime_error("Battle action bound exceeded");}bool won=g.report&&g.report->won;battles.push_back({{"day",started},{"target",target},{"fort",fort},{"won",won},{"actions",iterations}});std::cout<<"battle "<<battles.back().dump()<<std::endl;g.report.reset();choose();if(!g.computerQueue.empty())g.computerTurns();}choose();while(g.takeAdventureVisit())++visits;g.takeEvents();};
 for(int iteration=0;iteration<180&&!g.result;++iteration){resolve();if(g.result)break;g.manageKingdom(true);auto ids=g.ownedHeroes();for(int id:ids){if(g.result||!g.selectHero(id))break;g.manageKingdom(true);resolve();for(int action=0;action<100&&!g.result&&g.hero.movement>0&&g.heroes.contains(id);++action){int target=0;auto route=g.adventurePlan(&target);if(route.empty()||route.front().cost>g.hero.movement)break;auto before=g.hero.pos;int movement=g.hero.movement,level=g.mapLevel;auto reply=g.move({route.front().x,route.front().y});if(auto*site=g.objectById(target);site&&Game::extendedLocation(site->sourceClass)&&g.canVisitLocation(*site))g.autoVisitLocation(target);if(g.hero.pos!=before||g.mapLevel!=level)++moves;actions<<nlohmann::json{{"day",g.day},{"hero",id},{"target",target},{"from",{before.x,before.y,level}},{"to",{g.hero.pos.x,g.hero.pos.y,g.mapLevel}},{"movement",g.hero.movement},{"message",reply}}.dump()<<'\n';resolve();if(!g.heroes.contains(id)||g.result)break;g.manageKingdom(false);if(g.hero.pos==before&&g.mapLevel==level&&g.hero.movement==movement)break;}}
  int own=0,hostile=0;for(auto&o:g.objects)if(o.type==ObjectType::Town){own+=o.owner==0;hostile+=o.owner>0;}turns.push_back({{"day",g.day},{"towns",own},{"hostileTowns",hostile},{"heroes",g.ownedHeroes().size()},{"armyPower",g.armyPower(g.hero.army)},{"gold",g.resources[Gold]},{"level",g.mapLevel},{"moves",moves}});std::cout<<turns.back().dump()<<std::endl;
  if(!g.validate()){std::ofstream(out/"invalid-state.json")<<g.toJson().dump();throw std::runtime_error("Campaign state invalid");}if(!g.result){g.endDay();resolve();}
 }
 if(!g.save(out/"final.json",error))throw std::runtime_error(error);auto activity=g.scenarioRules.value("computerActivity",nlohmann::json::array());std::ofstream(out/"campaign-audit.json")<<nlohmann::json{{"map",g.scenarioId},{"sourceSha256",g.scenarioRules["sourceSha256"]},{"completed",g.result==1},{"result",g.result},{"day",g.day},{"moves",moves},{"visits",visits},{"normalGameplayOnly",true},{"reloads",0},{"faction",8},{"startingHero",131},{"difficulty",4},{"policy",legacy?"legacy-nearest-target":"threat-and-loss-aware"},{"videoDays",19},{"identicalToOriginalRules",false},{"turns",turns},{"battles",battles},{"computerActivity",activity}}.dump(2)<<'\n';std::cout<<"Video map result "<<g.result<<" day "<<g.day<<std::endl;return g.result==1?0:2;
 }catch(const std::exception&e){std::cerr<<"Video campaign: "<<e.what()<<std::endl;return 1;}}
